import type { CSSObject } from '@emotion/react';
import styled from '@emotion/styled';
import { Button, Card, Heading, Paragraph } from 'components/UI';
import { theme } from 'theme';

export const StyledPillarResourcesCard = styled(Card, {
  shouldForwardProp: (prop) => prop !== '$disabled',
})<{ $disabled?: boolean }>(({ $disabled }) => ({
  display: 'flex',
  width: '248px',
  height: '164px',
  padding: theme.spacing['4'],
  justifyContent: 'space-between',
  flexDirection: 'column',
  alignItems: 'flex-start',
  gap: theme.spacing['2'],
  cursor: 'pointer',
  boxShadow: 'none',
  animation: 'all 0.5s ease',

  '@media (min-width: 1440px)': {
    width: '288px',
  },
  '@media (min-width: 1920px)': {
    width: '335px',
  },

  '&:hover': {
    border: '1px solid #F5E003',
    boxShadow: 'none',
    background:
      'linear-gradient(180deg, rgba(255, 255, 255, 0.00) 40%, #E5B611 109.07%), #FFF',
  },

  ...($disabled && {
    opacity: 0.5,
    cursor: 'not-allowed',
    pointerEvents: 'none',
  }),
}));

export const StyledCardHeader = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  justifyContent: 'space-between',
  width: '100%',
  gap: '12px',
});

export const StyledHeaderLeft = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  gap: '12px',
  flex: 1,
  minWidth: 0,
});

interface StyledIconContainerProps {
  $highlighted?: boolean;
  $disabled?: boolean;
}

export const StyledIconContainer = styled.div<StyledIconContainerProps>(
  ({ $highlighted, $disabled }) => ({
    display: 'none',
    alignItems: 'center',
    justifyContent: 'center',
    width: '40px',
    height: '40px',
    minWidth: '40px',
    borderRadius: '50%',
    backgroundColor: '#141414a3',
    flexShrink: 0,

    '@media (min-width: 1920px)': {
      display: 'flex',
    },

    '& svg, & img': {
      width: '20px',
      height: '20px',
      color: '#FFFFFF',
    },

    ...($highlighted && {
      background: 'linear-gradient(217deg, #F5E003 0%, #D3A238 75%)',

      '& svg, & img': {
        color: '#141414',
      },
    }),
    ...($disabled && {
      backgroundColor: '#E0E0E0',
    }),
  }),
);

export const StyledTitleContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '2px',
  minWidth: 0,
  flex: 1,
});

interface StyledPillarLabelProps {
  $highlighted?: boolean;
  $disabled?: boolean;
}

export const StyledPillarLabel = styled(Paragraph, {
  shouldForwardProp: (prop) => !['$highlighted', '$disabled'].includes(prop),
})<StyledPillarLabelProps>(({ $highlighted, $disabled }) => ({
  display: 'none',
  fontSize: '12px !important',
  lineHeight: '12px !important',
  color: '#1414148f !important',
  margin: 0,
  fontWeight: '400',

  '@media (min-width: 1920px)': {
    display: 'block',
  },

  ...($highlighted && { color: '#1414148f' }),
  ...($disabled && { color: '#E0E0E0' }),
}));

interface StyledToolTitleProps {
  $disabled?: boolean;
}

export const StyledToolTitle = styled(Heading, {
  shouldForwardProp: (prop) => prop !== '$disabled',
})<StyledToolTitleProps>(({ $disabled }) => ({
  fontSize: '16px !important',
  lineHeight: '20px !important',
  color: '#141414',
  margin: 0,
  fontWeight: 'bold',
  ...($disabled && { color: '#E0E0E0' }),
}));

interface StyledFavoriteButtonProps {
  $disabled?: boolean;
  $isFavorite?: boolean;
}

export const StyledFavoriteButton = styled.button<StyledFavoriteButtonProps>(
  ({ $disabled, $isFavorite }) => ({
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: '24px',
    height: '24px',
    minWidth: '24px',
    border: 'none',
    background: 'transparent',
    cursor: 'pointer',
    padding: 0,
    flexShrink: 0,

    '& svg': {
      width: '20px',
      height: '20px',
      transition: 'color 150ms ease',
    },

    '&:hover svg': {
      color: '#e5b611',
    },

    ...($disabled && { cursor: 'not-allowed' }),
    ...($isFavorite && {
      svg: { color: 'rgba(229, 182, 17, 1)' },
    }),
    ...($isFavorite === false && {
      svg: { color: 'rgba(20, 20, 20, 1)' },
    }),
  }),
);

export const StyledCardBody = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  minHeight: '48px',
  flex: 1,
});

export const StyledDescription = styled(Paragraph)({
  fontSize: '12px !important',
  lineHeight: '20px !important',
  color: '#1414148f !important',
  margin: 0,
  display: '-webkit-box',
  WebkitLineClamp: 2,
  WebkitBoxOrient: 'vertical',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  wordBreak: 'break-word',
});

export const StyledCardFooter = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  gap: '8px',
  width: '100%',
  marginTop: 'auto',
});

export const StyledTagsWrapper = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  gap: '4px',
  flexWrap: 'wrap',
});

interface StyledReportButtonProps {
  $highlighted?: boolean;
  $disabled?: boolean;
}

export const StyledReportButton = styled(Button, {
  shouldForwardProp: (prop) => !['$highlighted', '$disabled'].includes(prop),
})<StyledReportButtonProps>(({ $highlighted, $disabled }) => ({
  borderRadius: '6px',
  padding: '8px 16px !important',
  fontSize: '14px !important',
  fontWeight: '500',
  backgroundColor: '#FFE5CC',
  color: '#D2691E',
  border: 'none',

  '&:hover': {
    backgroundColor: '#FFD9B3',
  },

  ...($highlighted && {
    backgroundColor: '#F5E003',
    color: '#D2691E',
    '&:hover': {
      backgroundColor: '#E5D003',
    },
  }),
  ...($disabled && {
    backgroundColor: '#F5F5F5',
    color: '#E0E0E0',
    cursor: 'not-allowed',
    pointerEvents: 'none',
  }),
}));

export const StyledComingSoonButton = styled(Button)({
  borderRadius: '6px',
  padding: '8px 16px !important',
  fontSize: '14px !important',
  fontWeight: '500',
  backgroundColor: '#F5F5F5',
  color: '#E0E0E0',
  border: 'none',
  cursor: 'not-allowed',
  pointerEvents: 'none',
});

export const StyledCardLink = styled.a({
  textDecoration: 'none',
  color: 'inherit',
});

