interface TagContainerProps {
  $density?: TagDensity;
  $color?: TagColor;
  $clickable?: boolean;
  $onColor?: boolean;
}

export const TagContainer = styled.div<TagContainerProps>(
  ({ $density = 'default', $color = 'black', $clickable, $onColor }) => ({
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: 'fit-content',
    borderRadius: theme.borderRadius['1'],
    color: theme.colors.neutral100,
    userSelect: 'none',
    fontFamily: theme.fonts.paragraph,
    fontWeight: theme.fonts.fontWeights.normal,
    minHeight: '24px',

    svg: {
      width: '16px',
      height: '16px',
    },

    ...tagDensityStyles[$density],
    ...tagColorStyles[$color],
    ...($clickable && {
      cursor: 'pointer',
      border: 'none',
      ...(tagClickableBorder[$color] && { border: tagClickableBorder[$color] }),
    }),
    ...($onColor && {
      transition: 'all 0.5s ease',
      backgroundColor: theme.colors.neutral0,
      border: 'none',
      ...(tagOnColorText[$color] && { color: tagOnColorText[$color] }),
    }),
  }),
);
